{
  "a_sentences": [
    {
      "a_text": "La question litigieuse porte sur la légalité de la décision sur opposition de l'assureur par laquelle il a affilié obligatoirement les travailleurs de la personne assurée avec effet au 1er janvier 2022.",
      "b_propositions": ["P1"]
    },
    {
      "a_text": "Il est constant que la personne assurée exploite une entreprise unitaire, ses activités se limitant aux travaux de nettoyage et aux services de conciergerie.",
      "b_propositions": ["P2"]
    },
    {
      "a_text": "Une entreprise unitaire entre dans le champ d'application de l'assurance obligatoire auprès de l'assureur lorsque son activité relève d'une des catégories énumérées à l'art. 66 al. 1 LAA.",
      "b_propositions": ["P3"]
    },
    {
      "a_text": "L'art. 66 al. 1 let. b LAA soumet à l'assurance obligatoire les travailleurs des entreprises de l'industrie du bâtiment, d'installations et de pose de conduites.",
      "b_propositions": ["P4"]
    },
    {
      "a_text": "L'art. 73 let. b OLAA précise que sont réputées entreprises de l'industrie du bâtiment, d'installations et de pose de conduites celles qui ont pour objet le nettoyage de bâtiments, de chaussées, de places et jardins publics.",
      "b_propositions": ["P5"]
    },
    {
      "a_text": "L'art. 73 let. b OLAA décrit de manière exhaustive les activités soumises à l'assurance obligatoire auprès de l'assureur.",
      "b_propositions": ["P6"]
    },
    {
      "a_text": "Le Tribunal administratif fédéral n'avait pas à exercer un contrôle en opportunité pour déterminer si l'affiliation de toutes les entreprises de nettoyage était judicieuse.",
      "b_propositions": ["P7"]
    },
    {
      "a_text": "L'assureur était fondé à affilier obligatoirement les travailleurs de la personne assurée avec effet au 1er janvier 2022.",
      "b_propositions": ["P8"]
    }
  ]
}
